export type ArabUniType = "government" | "private" | "technical";

export interface OfficialPortal {
  name: string;
  nameEn: string;
  url: string;
  description?: string;
  descriptionEn?: string;
}

export interface ArabUniversity {
  id: string;
  name: string;
  nameEn: string;
  country: string;
  countryEn: string;
  flag: string;
  city: string;
  cityEn?: string;
  type: ArabUniType;
  website: string;
  faculties: string[];
  minPercentage: number;
  language: "ar" | "en" | "mixed";
  scholarships: boolean;
  highlights: string;
  highlightsEn: string;
}

export interface ArabCountryMeta {
  country: string;
  countryEn: string;
  flag: string;
  code: string;
  scholarshipType: string;
  scholarshipTypeEn: string;
  officialPortals: OfficialPortal[];
  overview: string;
  overviewEn: string;
}

