// Order of the 8 countries: Sudan first (Permanent Anchor), followed by Saudi Arabia, Qatar, UAE, Egypt, Morocco, Oman, Jordan
export const ORDERED_COUNTRY_NAMES = [
  "المملكة العربية السعودية",
  "قطر",
  "الإمارات العربية المتحدة",
  "مصر",
  "المغرب",
  "سلطنة عُمان",
  "الأردن",
  "السودان",
];

export const ARAB_COUNTRIES = ORDERED_COUNTRY_NAMES.map((name) => {
  const meta = ARAB_COUNTRIES_META[name];
  return {
    country: meta.country,
    countryEn: meta.countryEn,
    flag: meta.flag,
  };
});

export const ARAB_FACULTIES = Array.from(
  new Set(ARAB_UNIVERSITIES.flatMap((u) => u.faculties))
).sort();

